import type { Column, Row } from "./types";

interface TableRowProps {
  row: Row;
  columns: Column[];
}

export function TableRow({ row, columns }: TableRowProps) {
  return (
    <tr>
      {columns.map((c) => (
        <td key={c.key} className={c.align === "right" ? "num" : undefined}>
          {String(row[c.key])}
        </td>
      ))}
    </tr>
  );
}

